// Local did:atp identity: a hybrid Ed25519 + ML-DSA-65 key pair generated by
// atp-sdk and stored in ~/.atp/identity.json with owner-only permissions.
// Secret keys are never printed or returned by describe().
import { existsSync, statSync } from 'node:fs';
import { CryptoUtils, DidAtp } from 'atp-sdk';
import { ensureHome, paths, readJson, writeJson } from './home.mjs';

const b64 = (bytes) => Buffer.from(bytes).toString('base64url');
const unb64 = (text) => new Uint8Array(Buffer.from(text, 'base64url'));

export class IdentityError extends Error {}

export async function createIdentity({ domain = 'localhost', name = 'agent', force = false } = {}) {
  const file = paths.identity();
  if (existsSync(file) && !force) {
    throw new IdentityError(`an identity already exists at ${file}; pass --force to replace it (the old keys are discarded)`);
  }
  const segments = String(name).split('/').filter(Boolean);
  if (segments.length === 0) throw new IdentityError('name must contain at least one path segment');
  const { did, keyPair } = await DidAtp.generate(domain, segments);
  ensureHome();
  writeJson(file, {
    version: 1,
    did,
    created: new Date().toISOString(),
    ed25519: { publicKey: b64(keyPair.ed25519.publicKey), secretKey: b64(keyPair.ed25519.secretKey) },
    mlDsa65: { publicKey: b64(keyPair.mlDsa65.publicKey), secretKey: b64(keyPair.mlDsa65.secretKey) },
  }, 0o600);
  return describeIdentity();
}

export function loadIdentity() {
  const file = paths.identity();
  const value = readJson(file);
  if (!value) return null;
  if (!value.did || !value.ed25519?.publicKey || !value.ed25519?.secretKey) throw new IdentityError(`${file} is not a valid ATP identity`);
  return value;
}

/** Public information only. */
export function describeIdentity() {
  const identity = loadIdentity();
  if (!identity) return null;
  const mode = statSync(paths.identity()).mode & 0o777;
  return {
    did: identity.did,
    created: identity.created,
    file: paths.identity(),
    fileMode: `0${mode.toString(8)}`,
    ownerOnly: (mode & 0o077) === 0,
    ed25519PublicKey: identity.ed25519.publicKey,
    e1Fingerprint: CryptoUtils.e1Fingerprint(unb64(identity.ed25519.publicKey)),
    pq1Fingerprint: identity.mlDsa65?.publicKey ? CryptoUtils.pq1Fingerprint(unb64(identity.mlDsa65.publicKey)) : null,
  };
}

/** Ed25519 signature over a UTF-8 string, returned with the signer's public key. */
export async function signWithIdentity(text) {
  const identity = loadIdentity();
  if (!identity) return null;
  const signature = await CryptoUtils.signEd25519(text, unb64(identity.ed25519.secretKey));
  return { did: identity.did, signer: identity.ed25519.publicKey, sig: b64(signature) };
}

export async function verifyIdentitySignature(text, signerB64, sigB64) {
  return CryptoUtils.verifyEd25519(text, unb64(sigB64), unb64(signerB64));
}
